#include <ros/ros.h>
#include <image_transport/image_transport.h>
#include <opencv2/opencv.hpp>

class CameraCalibrator {
  ros::NodeHandle nh;
  image_transport::ImageTransport it;
  image_transport::Subscriber sub;

public:
  CameraCalibrator() : it(nh) {
    // Subscribe to the camera topic
    sub = it.subscribe("camera_topic", 1, &CameraCalibrator::imageCb, this);
  }

  void imageCb(const sensor_msgs::ImageConstPtr& msg) {
    // Convert ROS image message to OpenCV image
    cv_bridge::CvImagePtr cv_ptr;
    try {
      cv_ptr = cv_bridge::toCvCopy(msg, "bgr8");
    } catch (cv_bridge::Exception& e) {
      ROS_ERROR("cv_bridge exception: %s", e.what());
      return;
    }

    // Calibrate camera using OpenCV functions
    // The actual calibration process would depend on the specific library and method used.
    Mat cameraMatrix, distCoeffs;
    double alpha = 0.1; // Calibration parameter
    Size patternSize(9, 6); // Define the chessboard pattern size in squares
    vector<vector<Point2f>> corners;

    // Detect chessboard corners (if available)
    bool found = findChessboardCorners(cv_ptr->image, patternSize, corners);

    if (found) {
      // Refine detected corners using sub-pixel accuracy
      cornerSubPix(cv_ptr->image, corners, Size(5, 5), Size(-1, -1),
